using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ApplyEffectDrawDieCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/ApplyEffectDrawDieCustomDescription", order = 0)]
public class ApplyEffectDrawDieCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		ApplyEffectDrawDieAction applyEffectDrawDieAction = battleAction as ApplyEffectDrawDieAction;
		bool usedAmountForDraw = applyEffectDrawDieAction.UsedAmountForDraw;
		string actionDescription = applyEffectDrawDieAction.EffectAction.GetActionDescription(usedAmountForDraw ? applyEffectDrawDieAction.DrawDiceAmount : GetAmountWithoutEquation(amountModified));
		string actionDescription2 = applyEffectDrawDieAction.DrawAction.GetActionDescription(usedAmountForDraw ? GetAmountWithoutEquation(amountModified) : applyEffectDrawDieAction.DrawDiceAmount);
		string text = "";
		if (applyEffectDrawDieAction.InvertDescriptions)
		{
			return actionDescription2 + "\n" + actionDescription;
		}
		return actionDescription + "\n" + actionDescription2;
	}
}
